25	export function sortEvents(events: BrEvent[]): BrEvent[] {
26	  return [...events].sort((a, b) => {
27	    const dt = Date.parse(a.ts) - Date.parse(b.ts);
28	    if (dt) return dt;
29	    const ds = a.source.localeCompare(b.source);
30	    if (ds) return ds;
