35	export function compileTimeline(
36	  events: BrEvent[],
37	  opts: { compress: boolean; prerollMs: number; realLimitMs: number | null },
38	): Timeline {
39	  const sorted = sortEvents(events);
40	  if (!sorted.length) {
41	    return { points: [], skips: [], duration: opts.prerollMs, t0: 0 };
42	  }
43	  const t0 = Date.parse(sorted[0].ts);
44	  const limited = opts.realLimitMs == null
45	    ? sorted
46	    : sorted.filter((event) => Date.parse(event.ts) - t0 <= opts.realLimitMs!);
47	  let virt = opts.prerollMs;
48	  let prevReal = 0;
49	  const points: TimelinePoint[] = [];
50	  const skips: Skip[] = [];
51	  for (const event of limited) {
52	    const real = Date.parse(event.ts) - t0;
53	    const gap = real - prevReal;
54	    if (opts.compress && gap > GAP) {
55	      skips.push({ at: virt, span: COMPRESSED, gap });
56	      virt += COMPRESSED;
57	    } else {
58	      virt += gap;
59	    }
60	    points.push({ virt, real, event });
61	    prevReal = real;
62	  }
63	  let duration = virt;
64	  if (!opts.compress && opts.realLimitMs != null) {
65	    duration = opts.prerollMs + opts.realLimitMs;
66	  } else {
67	    duration += 800;
68	  }
69	  return { points, skips, duration, t0 };
70	}
