72	export function agentPoint(agent: AgentState, w: number, h: number, now: number, reduced: boolean) {
73	  const [hx, hy] = homeOf(agent.index, w, h);
74	  const driftTime = agent.frozenAt != null && agent.releasedAt == null ? agent.frozenAt : now;
75	  const wob = reduced ? 0 : 1;
76	  const dx = Math.sin(driftTime / 1000 * 0.85 + agent.index) * 7 * wob;
77	  const dy = Math.cos(driftTime / 1000 * 0.62 + agent.index * 1.4) * 5 * wob;
78	  let x = hx + dx;
79	  let y = hy + dy;
80	
81	  const trip = [...agent.trips].reverse().find((item) => now >= item.at && now <= item.at + TRIP_MS);
82	  const traveling = trip && (agent.frozenAt == null || now < agent.frozenAt) && (agent.cagedAt == null || now < agent.cagedAt);
83	  if (traveling && trip) {
84	    const dest = servicePoint(trip.service, w, h);
85	    if (dest) {
86	      const u = along((now - trip.at) / TRIP_MS);
87	      x = hx + (dest[0] - hx) * u;
88	      y = hy + (dest[1] - hy) * u;
89	    }
90	  }
91	
92	  const [cx, cy] = cageOf(agent.index, w, h);
93	  if (agent.releasedAt != null && now >= agent.releasedAt) {
94	    const t = reduced ? 1 : clamp((now - agent.releasedAt) / 700, 0, 1);
95	    x = cx + (hx + dx - cx) * ease(t);
96	    y = cy + (hy + dy - cy) * ease(t);
97	  } else if (agent.cagedAt != null && now >= agent.cagedAt) {
98	    const t = reduced ? 1 : clamp((now - agent.cagedAt) / 700, 0, 1);
99	    x = x + (cx - x) * ease(t);
100	    y = y + (cy - y) * ease(t);
101	  }
102	
103	  if (agent.blockedAt != null && now >= agent.blockedAt && now < agent.blockedAt + 900) {
104	    const notes = servicePoint("notes", w, h);
105	    if (notes) {
106	      const u = (now - agent.blockedAt) / 900;
107	      const bounce = Math.sin(u * Math.PI);
108	      x = notes[0] - 46 - bounce * 18;
109	      y = notes[1] + (agent.index - 1) * 16;
110	    }
111	  }
112	
113	  return { x, y, hx, hy };
114	}
