118	  ctx.moveTo(x + r, y);
119	  ctx.arcTo(x + w, y, x + w, y + h, r);
120	  ctx.arcTo(x + w, y + h, x, y + h, r);
121	  ctx.arcTo(x, y + h, x, y, r);
122	  ctx.arcTo(x, y, x + w, y, r);
123	  ctx.closePath();
124	}
