304	function paintLabel(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, w: number, h: number, obstacles: Box[], muted: boolean) {
305	  const tw = ctx.measureText(text).width;
306	  const th = 16;
307	  const options = [
308	    { lx: x + 13, ly: y - 8 },
309	    { lx: x - tw - 13, ly: y - 8 },
310	    { lx: x - tw / 2, ly: y - 26 },
311	    { lx: x - tw / 2, ly: y + 10 },
312	  ];
313	  const hits = (lx: number, ly: number) => {
314	    const rect = { x: lx - 2, y: ly - 1, w: tw + 4, h: th };
315	    if (rect.x < 4 || rect.y < 4 || rect.x + rect.w > w - 4 || rect.y + rect.h > h - 4) return true;
316	    return obstacles.some((box) => !(rect.x + rect.w < box.x || box.x + box.w < rect.x || rect.y + rect.h < box.y || box.y + box.h < rect.y));
317	  };
318	  const spot = options.find((option) => !hits(option.lx, option.ly)) ?? options[0];
319	  ctx.fillStyle = muted ? MUTED : INK;
320	  ctx.fillText(text, spot.lx, spot.ly + 12);
321	}
