323	export function hitAgent(state: ViewState, w: number, h: number, x: number, y: number, now: number, reduced: boolean) {
324	  let found: string | null = null;
325	  for (const agent of Object.values(state.agents)) {
326	    const point = agentPoint(agent, w, h, now, reduced);
327	    if (Math.hypot(point.x - x, point.y - y) < 16) found = agent.id;
328	  }
329	  return found;
330	}

