20	function useReplayPlayer(replay: ReplayFile, opts: { compress: boolean; prerollMs: number; realLimitMs: number | null; loop: boolean }, active: boolean) {
21	  const [player, setPlayer] = useState<Player | null>(null);
22	  const [version, setVersion] = useState(0);
23	  const activeRef = useRef(active);
24	  const userPaused = useRef(false);
25	  activeRef.current = active;
26	
27	  useEffect(() => {
28	    const next = new Player(replay.events, replay.agents, opts);
29	    const off = next.subscribe(() => setVersion((value) => value + 1));
30	    next.seek(0);
31	    if (activeRef.current && !userPaused.current) next.play();
32	    setPlayer(next);
33	    return () => {
34	      off();
35	      next.destroy();
36	    };
37	    // The replay file is static for the life of the page.
38	    // eslint-disable-next-line react-hooks/exhaustive-deps
39	  }, [replay, opts.compress, opts.loop, opts.prerollMs, opts.realLimitMs]);
40	
41	  useEffect(() => {
42	    if (!player) return;
43	    if (active && !userPaused.current) player.play();
44	    if (!active) player.pause();
45	  }, [active, player]);
46	
47	  return { player, version, userPaused };
48	}
