58	function describe(event: BrEvent): string {
59	  const data = event.data;
60	  switch (event.type) {
61	    case "case.opened": return "Case opened";
62	    case "case.transition": return `${String(data.from ?? "")} → ${String(data.to ?? "")}`.replaceAll("_", " ");
63	    case "case.findings": return "Investigator findings in";
64	    case "case.verdict": return "Verifier verdict in";
65	    case "case.writeback": return "Written back to neatlogs";
66	    case "case.patched": return `Guardrail ${String(data.sha ?? "").slice(0, 7)}`;
67	    case "case.confirming": return "Confirmation re-runs";
68	    case "case.confirmed": return "Fix confirmed";
69	    case "case.remembered": return "Remembered in Brain";
70	    case "case.failed": return `Stopped at ${String(data.step ?? "a step")}`;
71	    case "agent.call": return `${String(data.tool ?? "call")} → ${String(data.service ?? "")}`;
72	    case "agent.blocked": return "Blocked by guardrail";
73	    default: return event.type;
74	  }
75	}
