149	function EventStack({ player }: { player: Player | null }) {
150	  const [last, setLast] = useState(-1);
151	  useEffect(() => {
152	    if (!player) return;
153	    const id = window.setInterval(() => {
154	      const points = player.timeline.points;
155	      let index = -1;
156	      for (let i = 0; i < points.length; i += 1) {
157	        if (points[i].virt <= player.virt) index = i;
158	        else break;
159	      }
160	      setLast(index);
161	    }, 160);
162	    return () => window.clearInterval(id);
163	  }, [player]);
164	
165	  if (!player) return null;
166	  const points = player.timeline.points;
167	  const rows = [];
168	  for (let index = last; index >= 0 && index > last - 3; index -= 1) rows.push({ index, point: points[index] });
169	
170	  return (
171	    <ol className="events glass" aria-label="Latest events in the replay">
172	      {rows.length === 0 && <li className="idle"><span className="ev-dot" />Watching traces</li>}
173	      {rows.map(({ index, point }, row) => (
174	        <li key={index} className={row === 0 ? "fresh" : ""}>
175	          <span className="ev-dot" />
176	          <span className="ev-text">{describe(point.event)}</span>
177	          <span className="ev-meta">{agentLabel(point.event.agent)} · {formatClock(player.timeline.t0, point.real)}</span>
178	        </li>
179	      ))}
180	    </ol>
181	  );
182	}
