      bounces += Object.values(p.state.agents).filter((a) => a.blockedAt != null && v >= a.blockedAt && v < a.blockedAt + 250).length;
      for (const a of Object.values(p.state.agents)) {
        if (rerunAlpha(a, v) === 0) continue;
        const { x, y } = agentPoint(a, 640, 420, v, true);
        if (x < 0 || y < 0 || x > 640 || y > 420) outOfField++;
      }
      if (v % 20000 === 0) {
        const s = p.state;
        const st = s.order.map((id) => s.cases[id].status).join(",");
        const live = replay.agents.map((id: string) => `${s.agents[id].trips.length}${s.agents[id].trail === "red" ? "R" : ""}${s.agents[id].cagedAt != null ? "C" : ""}`).join(" ");
        console.log(`${(v / 1000).toFixed(0).padStart(4)}s ${formatClock(tl.t0, realOf(tl, v))} live[${live}] reruns-on ${on.length} cases ${st || "-"}`);
      }
    }
    console.log(`peak reruns on stage ${peak}, bounce samples ${bounces}, dots outside field ${outOfField}`);
  }
});

function realOf(tl: { points: { virt: number; real: number }[] }, v: number) {
  let r = 0;
  for (const pt of tl.points) { if (pt.virt <= v) r = pt.real; else break; }
  return r;
}
